<?php $page_title='Master kategori'; $this->load->view('staff/_layout_start',compact('user','page_title')); $can_edit=in_array($user['role_code'],array('superadmin','admin_dinas'),TRUE); ?>
<section class="staff-hero"><div><span class="staff-kicker">MASTER DATA</span><h1>Kategori etalase</h1><p>Kategori ini dipakai untuk navigasi toko dan produk. KBLI dan skala usaha tercatat pada master terpisah.</p></div></section>
<?php $master_tab='categories';$this->load->view('staff/_master_tabs',compact('master_tab')); ?>
<?php if ($this->input->get('tersimpan')): ?><div class="alert alert-success" role="status">Kategori berhasil disimpan.</div><?php endif; ?>
<?php if ($error): ?><div class="alert alert-danger" role="alert"><?= html_escape($error) ?></div><?php endif; ?>
<section class="staff-panel"><h2>Daftar kategori</h2><form class="staff-list-filter" method="get" action="<?= site_url('pengelola/master/kategori') ?>"><label>Cari kategori<input class="form-control" type="search" name="q" maxlength="80" value="<?= html_escape($search) ?>" placeholder="Nama atau slug"></label><label>Status<select class="form-select" name="status"><option value="">Semua</option><option value="active" <?= $status==='active'?'selected':'' ?>>Aktif</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Nonaktif</option></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button><a href="<?= site_url('pengelola/master/kategori') ?>">Reset</a></form><p class="staff-list-count"><?= number_format($total,0,',','.') ?> kategori</p>
<?php if (!$rows): ?><p>Kategori tidak ditemukan.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Kategori</th><th>Induk</th><th>Slug</th><th>Urutan</th><th>Status</th><?php if ($can_edit): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= html_escape($row['name']) ?></strong></td><td><?= html_escape($row['parent_name']?:'Kategori utama') ?></td><td><code><?= html_escape($row['slug']) ?></code></td><td><?= (int)$row['sort_order'] ?></td><td><?= $row['is_active']?'Aktif':'Nonaktif' ?></td><?php if ($can_edit): ?><td><a href="<?= site_url('pengelola/master/kategori').'?edit='.(int)$row['id'] ?>">Ubah</a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/master/kategori'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
<?php if ($can_edit): ?><section class="staff-panel"><h2><?= $edit?'Ubah kategori':'Tambah kategori' ?></h2><p>Slug tidak berubah setelah kategori dibuat karena dipakai oleh gambar dan tautan etalase.</p><form method="post" action="<?= site_url('pengelola/master/kategori/simpan') ?>" class="master-form"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="id" value="<?= $edit?(int)$edit['id']:0 ?>"><label>Nama kategori<input class="form-control" name="name" required minlength="2" maxlength="120" value="<?= html_escape($edit?$edit['name']:'') ?>"></label><label>Slug<input class="form-control" name="slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="100" <?= $edit?'readonly':'' ?> value="<?= html_escape($edit?$edit['slug']:'') ?>"></label><label>Induk kategori<select class="form-select" name="parent_id"><option value="0">Kategori utama</option><?php foreach($parents as $parent): if ($edit && $parent['id']==$edit['id']) continue; ?><option value="<?= (int)$parent['id'] ?>" <?= $edit && $edit['parent_id']==$parent['id']?'selected':'' ?>><?= html_escape($parent['name']) ?></option><?php endforeach; ?></select></label><label>Urutan<input class="form-control" type="number" name="sort_order" min="0" max="9999" value="<?= $edit?(int)$edit['sort_order']:0 ?>"></label><label>Deskripsi<input class="form-control" name="description" maxlength="255" value="<?= html_escape($edit?$edit['description']:'') ?>"></label><label>Status<select class="form-select" name="is_active"><option value="1" <?= !$edit || $edit['is_active']?'selected':'' ?>>Aktif</option><option value="0" <?= $edit && !$edit['is_active']?'selected':'' ?>>Nonaktif</option></select></label><div class="master-actions"><button class="btn btn-primary" type="submit">Simpan kategori</button><?php if ($edit): ?><a class="btn btn-outline-primary" href="<?= site_url('pengelola/master/kategori') ?>">Batal ubah</a><?php endif; ?></div></form></section><?php endif; ?>
<?php $this->load->view('staff/_layout_end'); ?>
